package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class ApplyClaim {
    // Claim is a record, so the edited claim is published in place of the loaded one.
    public void apply(@Val ClaimInput input, @Val Claim claim, Claims claims, Sheets sheets,
            ServerHttpConnection connection, Out<ClaimResponse> responseOut) {
        Claim edited = claim.with(input, input.date() != null ? input.date() : sheets.today(claim.sheetId()));
        claims.save(edited, Audit.user(connection).trim());
        responseOut.set(ClaimResponse.from(edited));
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class AuditClaimEdited {
    // The loaded claim names the sheet and person; the edited one (as the screen sees it) the values.
    public void audit(@Val Claim loaded, @Val ClaimResponse edited, People people,
            ServerHttpConnection connection, Audit audit) {
        Person person = people.find(loaded.sheetId(), loaded.personId());
        List<String> fields = new ArrayList<>(List.of("person=" + (person == null ? "" : person.name()),
                "amount=" + edited.amount(), "date=" + edited.date()));
        if (edited.number() != null) {
            fields.add("number=" + edited.number());
        }
        audit.record(Audit.line("CLAIM_EDITED", loaded.sheetId(), Audit.user(connection),
                fields.toArray(String[]::new)));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class RefuseLockedClaim {
    // A claim whose editor another user has open cannot be edited until they save or cancel it.
    public void refuse(@Val Claim claim, ServerHttpConnection connection, ClaimLocks locks) throws ClaimLockedException {
        String by = locks.lockedBy(claim);
        if (by != null && !by.equals(Audit.user(connection).trim())) {
            throw new ClaimLockedException("The claim is being edited by " + by + ".");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class RefuseNonDraftClaim {
    // Only a draft can be edited; an open claim is changed by voiding it and adding a new one.
    public void refuse(@Val Claim claim) throws ClaimNotDraftException {
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new ClaimNotDraftException("A " + claim.status()
                    + " claim cannot be edited: only a draft can. Void it and add a new one.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.plugin.variable.Val;

public class RefuseClosedClaim {
    // A claim belongs to the period its due-by falls in: one due by a date inside a closed period cannot be edited,
    // opened, settled or voided.
    public void refuse(@Val Claim claim, Periods periods) throws ClaimInClosedPeriodException {
        Period closed = periods.closedOn(claim.sheetId(), claim.dueBy());
        if (closed != null) {
            throw new ClaimInClosedPeriodException("The period " + closed.name() + " is closed: its claims cannot change.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

public class RefuseRetiredClaim {
    // The date a claim is being edited to (a blank date is the sheet's today) must not be after its person's retirement.
    public void refuse(@Val ClaimInput input, @Val Claim claim, People people, Sheets sheets)
            throws ClaimAfterRetirementException {
        RefuseRetiredInput.check(people.find(claim.sheetId(), claim.personId()),
                input.date() != null ? input.date() : sheets.today(claim.sheetId()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class RefuseInvalidCorrectionClaim {
    // A claim edited into a correction must name, by number, a SETTLED claim of its own person, and take
    // back no more than remains of it, its own earlier amount left out.
    public void refuse(@Val ClaimInput input, @Val Claim claim, Claims claims) throws InvalidClaimException {
        RefuseInvalidCorrection.refuse(input, claim.sheetId(), claim.personId(), claim.id(), claims);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;

public class RefuseUsedRefClaim {
    // A claim being edited may keep its own reference, but not take one another claim of the sheet carries (ignoring case).
    public void refuse(@Val ClaimInput input, @Val Claim claim, Claims claims) throws InvalidClaimException {
        RefuseUsedRef.refuse(input.ref(), claim.sheetId(), claim.id(), claims);
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.plugin.variable.Val;

public class RefuseLinedAmount {
    // A claim with lines has their sum as its amount: an edit typing another amount is refused.
    public void refuse(@Val ClaimInput input, @Val Claim claim, Claims claims) throws ClaimLineRefusedException {
        List<ClaimLine> lines = claims.lines(claim);
        if (!lines.isEmpty() && input.amount().compareTo(ClaimLines.total(lines)) != 0) {
            throw new ClaimLineRefusedException("The claim's amount is its lines added up ("
                    + ClaimLines.total(lines).toPlainString() + "): it cannot be typed.");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class ReleaseClaimLock {
    // Saving or cancelling the editor releases the user's lock on the claim.
    public void release(@Val Claim claim, ServerHttpConnection connection, ClaimLocks locks) {
        locks.release(claim, Audit.user(connection).trim());
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class SnapshotRollup {
    // The sheet's figures before the change, for AuditRollup to compare with after it.
    public void snapshot(@PathVariable("sheetId") String sheetId, Rollup rollup, Out<Figures> before) {
        before.set(rollup.figures(sheetId.trim()));
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class AuditRollup {
    // After the change's own lines: one ROLLUP per person whose figures moved (a new person counts as moved),
    // in the order they were added, then TOTALS when a sheet total moved.
    public void audit(@PathVariable("sheetId") String sheetId, @Val Figures before, Rollup rollup,
            ServerHttpConnection connection, Audit audit) {
        RollupLines.record(sheetId.trim(), Audit.user(connection), before, rollup, audit);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");

    private static final Pattern NUMBER = Pattern.compile("\\d{1,18}|.{1,280}-\\d{1,18}");

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    // The amount is required; a blank date takes the sheet's today (filled in when stored); the note may be empty.
    // A negative amount is a correction and must name the number it corrects; no other claim may name one.
    // Whether that number is a SETTLED claim of the same person is checked once the person is loaded.
    // The external reference is kept without surrounding spaces; whether the sheet already uses it is checked once loaded.
    public void validate(@RequestBody ClaimRequest body, Out<ClaimInput> input) throws InvalidClaimException {
        input.set(parse(body));
    }

    /** The claim form's rules on a typed body; shared with the paste box, which checks every line by them. */
    static ClaimInput parse(ClaimRequest body) throws InvalidClaimException {
        String amount = body == null || body.amount() == null ? "" : body.amount().trim();
        String date = body == null || body.date() == null ? "" : body.date().trim();
        String note = body == null || body.note() == null ? "" : body.note().trim();
        String corrects = body == null || body.corrects() == null ? "" : body.corrects().trim();
        String ref = body == null || body.ref() == null ? "" : body.ref().trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() < 0 && corrects.isEmpty()) {
            throw new InvalidClaimException("A negative amount is a correction: name the number of the settled claim it corrects.");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a claim with a negative amount corrects another.");
        }
        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("Not a claim number: " + corrects);
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date, ISO);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("Not a date (yyyy-mm-dd): " + date);
            }
        }
        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects,
                ref.isEmpty() ? null : ref, tags(body == null ? null : body.tags()));
    }

    /** Comma separated tags as a claim keeps them: each trimmed and lower-cased, blanks and repeats dropped, sorted. */
    static List<String> tags(String typed) {
        if (typed == null) {
            return List.of();
        }
        return Arrays.stream(typed.split(",")).map(t -> t.trim().toLowerCase(Locale.ROOT)).filter(t -> !t.isEmpty())
                .distinct().sorted().toList();
    }
}

